const fs = require('fs');

function POWER(base, expo) {
    let num = 1;
    let i = expo;
    while (i) {
        num = num * base;
        i--;
    }
    return num;
}

function main() {
    const input = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    let ptr = 0;
    const next = () => input[ptr++];

    let t = 1; // parseInt(next());
    while (t--) {
        let n = parseInt(next());
        let m = parseInt(next());
        let k = parseInt(next());
        let a = [];
        for (let i = 0; i < n; i++) {
            a.push(parseInt(next()));
        }
        a.sort((x, y) => x - y);

        if (m <= k) {
            console.log(0);
        } else {
            let sum = 0;
            let i = n;
            let devices = m;
            let soc = k;
            while (sum < m && devices > soc && i >= 1) {
                i--;
                sum += a[i];
                devices -= a[i];
                soc--;
            }
            if (devices <= soc) {
                console.log(n - i);
            } else {
                let idx = n;
                let used = 0;
                let ss = 0;
                let j = 0;
                while (idx >= 1 && ss < m) {
                    idx--;
                    if (used >= k * j && j >= 1) ss--;
                    ss += a[idx];
                    used++;
                    if (used % k === 0 && used !== 0) j++;
                }
                if (ss >= m) console.log(used);
                else console.log(-1);
            }
        }
    }
}

main();

